SELECT _CAST(id, 'Tuple(UInt64, LowCardinality(UUID))') AS id, _CAST(samples, 'Array(Tuple(DateTime64(3), Float64))') AS samples FROM (SELECT id, timeSeriesSliceSortedArray(samples, toDateTime64(toDecimal128('1793501700', 3), 3), toDateTime64(toDecimal128('1793502000', 3), 3)) AS samples FROM default.`.inner_id.recentsamples.0ba209a5-cb50-4f17-98f0-4cf794d65ecc` WHERE and(greaterOrEquals(bucket, toDateTime64(toDecimal128('1793501100', 3), 3)), lessOrEquals(bucket, toDateTime64(toDecimal128('1793502000', 3), 3)), greaterOrEquals(max_time, toDateTime64(toDecimal128('1793501700', 3), 3)), lessOrEquals(min_time, toDateTime64(toDecimal128('1793502000', 3), 3)), in(id, (SELECT timeSeriesStoreTags(id, tags, '__name__', metric_name) FROM default.`.inner_id.tags.0ba209a5-cb50-4f17-98f0-4cf794d65ecc` ALL LEFT JOIN (SELECT id, 1 AS matched FROM default.`.inner_id.timeranges.0ba209a5-cb50-4f17-98f0-4cf794d65ecc` WHERE and(greaterOrEquals(max_time, toDateTime64(toDecimal128('1793501700', 3), 3)), lessOrEquals(min_time, toDateTime64(toDecimal128('1793502000', 3), 3)), and(greaterOrEquals(id, tuple(sipHash64('metric_1'), toUUID('00000000-0000-0000-0000-000000000000'))), lessOrEquals(id, tuple(sipHash64('metric_1'), toUUID('ffffffff-ffff-ffff-ffff-ffffffffffff')))))) AS time_ranges_subquery USING (id) WHERE and(and(equals(metric_name, 'metric_1'), equals(arrayElement(tags, 'job'), 'job3')), or(equals(time_ranges_subquery.matched, 1), notEquals(tupleElement(id, 1), sipHash64('metric_1')))))))) WHERE notEmpty(samples)